        "name": a["name"],
        "category": a.get("category", ""),
        "cpu": a.get("cpu", 0),
        "paramCount": a.get("params", 0),
        "minBlocks": a.get("min_blocks", 0),
        "maxBlocks": a.get("max_blocks", 0),
        "defaultBlocks": a.get("default_blocks", 0),
        "blocks": blocks,
        "options": opts_a,
        "paramDefaults": a.get("param_defaults", {}),
        "doc": doc,
